mapper.select:
select wf.id,wf.nick_name as nickName,wf.open_id as openId,wf.register_mobile as mobile, wf.crt_time as crtTime,wf.bind as isBind,wf.fans_status as fansStatus,wf.address, wfb.patient_id as patientId,pbi.name as name,wfb.dictionary_id as dictionaryId, case when wf.sex = 1 then '男' when wf.sex = 2 then '女' else '未知' end as sex from wx_fans wf LEFT JOIN wx_fans_bind wfb ON wf.open_id = wfb.open_id LEFT JOIN patient_base_info pbi on wfb.patient_id = pbi.id
and DATE_FORMAT(wf.crt_time,'%Y-%m-%d') >= DATE_FORMAT(#{startTime},'%Y-%m-%d') and DATE_FORMAT(wf.crt_time,'%Y-%m-%d') <= DATE_FORMAT(DATE_ADD(#{endTime},INTERVAL '1' DAY),'%Y-%m-%d')
and wf.bind = #{isBind}
and wf.address = #{address}
AND concat(IFNULL(pbi.`name`,''), IFNULL(pbi.medical_number,''), IFNULL(pbi.pinyin_name,''), IFNULL(wf.register_mobile,''), IFNULL(wf.nick_name,'')) like concat(concat('%', rtrim(#{name})), '%')
order by wf.crt_time desc

SELECT ROUND( 6378.138 * 2 * ASIN( SQRT( POW( SIN( ( #{latitude}*PI()/180-wf.latitude*PI()/180)/2),2)+ COS( #{latitude}*PI()/180)*COS(wf.latitude*PI()/180)*POW(SIN((#{longitude}*PI()/180- wf.longitude * PI() / 180 ) / 2 ), 2 ) ) ) * 1000 ) AS distance, wf.id as id, wf.longitude, wf.latitude, wf.bind as isBind, wf.nick_name as nickName, pbi.name as name FROM wx_fans AS wf left join patient_base_info pbi on wf.patient_id = pbi.id
and wf.fans_status = 2
and wf.bind = #{isBind}
HAVING distance <= #{distance}

SELECT ROUND( 6378.138 * 2 * ASIN( SQRT( POW( SIN( ( #{latitude}*PI()/180-wf.latitude*PI()/180)/2),2)+ COS( #{latitude}*PI()/180)*COS(wf.latitude*PI()/180)*POW(SIN((#{longitude}*PI()/180- wf.longitude * PI() / 180 ) / 2 ), 2 ) ) ) * 1000 ) AS distance, COUNT( CASE WHEN bind = 1 THEN 1 ELSE NULL END ) AS numBind, COUNT( CASE WHEN bind = 0 THEN 1 ELSE NULL END ) AS numNoBind FROM wx_fans AS wf
and wf.fans_status = 2
HAVING distance <= #{distance}
